        bestv = 10**18
        for ddx, ddy in legal:
            nx, ny = sx + ddx, sy + ddy
            v = man(nx, ny, tx, ty)
            if v < bestv:
                bestv = v
                best = (ddx, ddy)
        return best if best is not None else (0, 0)

